 import { AppError } from "../errors.js";

+/** Checks that `site` exists in the store and returns its id. */
+export function checkSite(store, site = "main") {
+  const s = typeof site === "object" && site !== null ? (site.site ?? "main") : site;
+  if (!(store.data.sites ?? []).some((x) => x.id === s)) throw new AppError("unknown_site", { id: s });
+  return s;
+}
+
+/** Whether `location` belongs to `site`. */
+export function inSite(store, location, site = "main") {
+  const s = checkSite(store, site);
+  return store.data.locations.some((l) => l.id === location && (l.site ?? "main") === s);
+}
